session_start();include('dbstring.php');include('check-login.php');include_once('user-management-utils.php');include_once('alumni-utils.php');if(!um_is_admin_manager()){header('location:index.php');exit();}alumni_ensure_tables($con);if(empty($_SESSION['alumni_concern_admin_csrf']))$_SESSION['alumni_concern_admin_csrf']=bin2hex(random_bytes(32));
if(isset($_POST['update_concern'])){if(hash_equals($_SESSION['alumni_concern_admin_csrf'],(string)($_POST['csrf']??''))){$id=(int)($_POST['concernid']??0);$status=trim((string)($_POST['status']??'new'));$note=trim((string)($_POST['adminnote']??''));if($id>0&&in_array($status,array('new','reviewing','resolved','closed'),true)){$stmt=mysqli_prepare($con,'UPDATE tblalumniconcern SET status=?,adminnote=? WHERE concernid=?');mysqli_stmt_bind_param($stmt,'ssi',$status,$note,$id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['alumni_concern_admin_flash']='Concern updated.';}}header('location:alumni-concerns.php');exit();}
$flash=$_SESSION['alumni_concern_admin_flash']??'';unset($_SESSION['alumni_concern_admin_flash']);$rows=mysqli_query($con,"SELECT c.*,a.fullname,a.graduationyear,a.email,a.mobile FROM tblalumniconcern c INNER JOIN tblalumni a ON a.alumniid=c.alumniid ORDER BY CASE c.status WHEN 'new' THEN 0 WHEN 'reviewing' THEN 1 ELSE 2 END,c.createdat DESC");
?><!doctype html><html><head><?php include('links.php');?><title>Alumni Concerns</title><style>:root{--n:#102b4b;--t:#08766f;--p:#f4f7fb;--l:#dce5ed}*{box-sizing:border-box}body{margin:0;background:var(--p);color:#1e293b;font:15px Arial,sans-serif}.wrap{max-width:1180px;margin:auto;padding:30px 18px 60px}.hero{padding:29px;border-radius:18px;background:linear-gradient(120deg,var(--n),var(--t));color:#fff}.hero h1{font:600 30px Georgia,serif;margin:5px 0}.hero p{margin:0;color:#dbeaf0}.back{display:inline-block;margin-top:13px;padding:10px 13px;border-radius:8px;background:#fff;color:var(--n);text-decoration:none;font-weight:bold}.flash{background:#e4f8ee;color:#126443;padding:13px;border-radius:9px;margin-top:15px}.item{margin-top:18px;background:#fff;border:1px solid var(--l);border-radius:15px;padding:21px}.item h2{font:600 21px Georgia,serif;color:var(--n);margin:0 0 6px}.meta{color:#64748b;font-size:13px}.message{margin:17px 0;padding:14px;border-left:4px solid #08766f;background:#f6fafb;white-space:pre-wrap;line-height:1.55}form{display:grid;grid-template-columns:170px 1fr auto;gap:10px;align-items:end}label{font-size:12px;font-weight:bold;color:#475569}select,textarea{display:block;width:100%;margin-top:5px;border:1px solid #c8d6e2;border-radius:8px;padding:10px;font:inherit}textarea{min-height:54px}button{border:0;background:var(--t);color:#fff;border-radius:8px;padding:11px 14px;font-weight:bold;cursor:pointer}@media(max-width:700px){form{grid-template-columns:1fr}button{width:100%}}</style></head><body><main class="wrap"><section class="hero"><small>AYISEC ALUMNI ADMINISTRATION</small><h1>Private Alumni concerns</h1><p>Review and follow up on feedback sent by verified old students.</p><a class="back" href="alumni-hub.php">← Alumni Hub</a></section><?php if($flash!==''){?><p class="flash"><?php echo alumni_safe($flash);?></p><?php }?><?php if($rows&&mysqli_num_rows($rows)>0){while($row=mysqli_fetch_assoc($rows)){?><article class="item"><h2><?php echo alumni_safe($row['subject']);?></h2><div class="meta"><b><?php echo alumni_safe($row['fullname']);?></b> · Class of <?php echo alumni_safe($row['graduationyear']);?> · <?php echo alumni_safe($row['category']);?> · <?php echo alumni_safe(date('d M Y, g:i a',strtotime($row['createdat'])));?><br><?php echo alumni_safe($row['email']);?> <?php echo $row['mobile']?' · '.alumni_safe($row['mobile']):'';?></div><div class="message"><?php echo nl2br(alumni_safe($row['messagebody']));?></div><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe($_SESSION['alumni_concern_admin_csrf']);?>"><input type="hidden" name="concernid" value="<?php echo (int)$row['concernid'];?>"><label>Status<select name="status"><?php foreach(array('new','reviewing','resolved','closed') as $status){?><option <?php echo $row['status']===$status?'selected':'';?>><?php echo $status;?></option><?php }?></select></label><label>Private follow-up note<textarea name="adminnote"><?php echo alumni_safe($row['adminnote']);?></textarea></label><button name="update_concern">Save update</button></form></article><?php }}else{?><article class="item"><p>No Alumni concerns have been submitted.</p></article><?php }?></main></body></html>
